        if not (0 <= nx < w and 0 <= ny < h):
            continue
        if (nx, ny) in bad:
            continue
        s = 0
        d = abs(nx - tx) + abs(ny - ty)
        s -= d * 3
        if resources and (nx, ny) in resources:
            s += 50
        s -= abs(nx - ox) + abs(ny - oy)
        if (dx, dy) == (0, 0):
            s -= 1
        if s > bests or (s == bests and (dx, dy) < best):
            bests = s
            best = (dx, dy)

    return [int(best[0]), int(best[1])]

